<?php require __DIR__.'/_lib/config.php';require __DIR__.'/_lib/sipsn_lib.php';need(['admin','petugas']);$adm=user()['role']=='admin';sipsn_ensure();
$msg='';$errs=[];$NEED=['tahun','periode','nama_provinsi','nama_kabkota','jml_timbulan_harian','jml_timbulan_tahun'];
if($_SERVER['REQUEST_METHOD']=='POST'){chk();if(!$adm)die('Khusus admin');$f=$_FILES['csv']??null;
if(!$f||$f['error']||$f['size']>1048576||strtolower(pathinfo($f['name'],PATHINFO_EXTENSION))!='csv')$errs[]='Pilih file .csv (maksimal 1 MB).';
else{$h=fopen($f['tmp_name'],'r');$first=(string)fgets($h);rewind($h);$d=substr_count($first,';')>substr_count($first,',')?';':',';
$hd=array_map(fn($x)=>strtolower(trim(preg_replace('/^\xEF\xBB\xBF/','',(string)$x))),(array)fgetcsv($h,0,$d));
if(array_diff($NEED,$hd))$errs[]='Kolom wajib: '.implode(', ',$NEED);
else{$ix=array_flip($hd);$n=0;$ok=[];$seen=[];$num=fn($v)=>preg_match('/^\d+([.,]\d+)?$/',trim((string)$v))?(float)str_replace(',','.',trim($v)):null;
while(($r=fgetcsv($h,0,$d))!==false){if(!array_filter($r,fn($v)=>trim((string)$v)!==''))continue;$n++;$g=fn($k)=>trim((string)($r[$ix[$k]]??''));
$th=$g('tahun');$pr=$g('periode');$pv=$g('nama_provinsi');$kb=$g('nama_kabkota');$hr=$num($g('jml_timbulan_harian'));$tt=$num($g('jml_timbulan_tahun'));$key="$th|$pr|$kb";
if(!ctype_digit($th)||$th<2000||$th>2100||$pr===''||strlen($pr)>10||$pv===''||$kb===''||strlen($kb)>80||strlen($pv)>60||$hr===null||$tt===null)$errs[]="Baris data ke-$n tidak valid.";
elseif(isset($seen[$key]))$errs[]="Baris data ke-$n duplikat di dalam file ($kb, $th).";
else{$seen[$key]=1;$ok[]=[(int)$th,$pr,$pv,$kb,$hr,$tt];}}
if(!$n)$errs[]='File tidak berisi data.';
if(!$errs){try{$db->beginTransaction();sipsn_upsert($ok);q('INSERT INTO sipsn_imports(source,rows_read,rows_saved,rows_rejected,user_id) VALUES(?,?,?,0,?)',[substr($f['name'],0,150),$n,count($ok),user()['id']]);$db->commit();$msg="Import berhasil: $n baris divalidasi dan disimpan. Data yang sama diperbarui, bukan digandakan.";}catch(Exception $x){if($db->inTransaction())$db->rollBack();$errs[]='Gagal menyimpan ke database.';}}
else $errs=array_slice($errs,0,6);}fclose($h);}}
$yrs=array_column(q('SELECT DISTINCT tahun FROM waste_generation_sipsn ORDER BY tahun')->fetchAll(),'tahun');$pers=array_column(q('SELECT DISTINCT periode FROM waste_generation_sipsn ORDER BY 1')->fetchAll(),'periode');
$w=['1=1'];$p=[];$sq=trim($_GET['q']??'');if($sq!==''){$w[]='nama_kabkota LIKE ?';$p[]='%'.$sq.'%';}
$ty=$_GET['tahun']??'';if(in_array($ty,array_map('strval',$yrs),true)){$w[]='tahun=?';$p[]=$ty;}else $ty='';
$tp=$_GET['periode']??'';if(in_array($tp,$pers,true)){$w[]='periode=?';$p[]=$tp;}else $tp='';
$S=['tahun_desc'=>'tahun DESC,nama_kabkota','tahun_asc'=>'tahun,nama_kabkota','harian_desc'=>'jml_timbulan_harian DESC','harian_asc'=>'jml_timbulan_harian','tahunan_desc'=>'jml_timbulan_tahun DESC','tahunan_asc'=>'jml_timbulan_tahun','nama'=>'nama_kabkota,tahun'];$so=isset($S[$_GET['urut']??''])?$_GET['urut']:'tahun_desc';
$W=implode(' AND ',$w);$cols='tahun,periode,nama_provinsi,nama_kabkota,jml_timbulan_harian,jml_timbulan_tahun';
if(($_GET['export']??'')=='csv'){while(ob_get_level())ob_end_clean();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="timbulan_sampah_sipsn.csv"');echo "\xEF\xBB\xBF";$o=fopen('php://output','w');fputcsv($o,$NEED);foreach(q("SELECT $cols FROM waste_generation_sipsn WHERE $W ORDER BY {$S[$so]}",$p)->fetchAll(PDO::FETCH_NUM) as $r)fputcsv($o,$r);exit;}
$tot=(int)q("SELECT COUNT(*) c FROM waste_generation_sipsn WHERE $W",$p)->fetch()['c'];$lim=15;$pages=max(1,(int)ceil($tot/$lim));$pg=min($pages,max(1,(int)($_GET['page']??1)));
$rows=q("SELECT $cols FROM waste_generation_sipsn WHERE $W ORDER BY {$S[$so]} LIMIT $lim OFFSET ".(($pg-1)*$lim),$p)->fetchAll();
$last=q('SELECT * FROM sipsn_imports ORDER BY id DESC LIMIT 1')->fetch();$all=(int)q('SELECT COUNT(*) c FROM waste_generation_sipsn')->fetch()['c'];
$qs=fn($pp)=>'?'.http_build_query(array_merge($_GET,['page'=>$pp]));
admin_head('Data Timbulan Sampah','sipsn');?>
<?php if($msg):?><div class="alert alert-success"><?=e($msg)?></div><?php endif;foreach($errs as $x):?><div class="alert alert-danger py-2"><?=e($x)?></div><?php endforeach?>
<div class="row g-3 mb-3"><div class="col-lg-8"><div class="card card-eco p-3 h-100"><div class="d-flex justify-content-between flex-wrap gap-2"><b>Dataset SIPSN KLHK &ndash; Provinsi Lampung</b><span class="small text-muted"><?=$all?> baris tersimpan<?=$last?' &middot; import terakhir: '.e($last['imported_at']).' ('.e($last['source']).')':''?></span></div><p class="small text-muted mb-0 mt-2"><?=e(UNIT_NOTE)?> Dataset belum memuat koordinat, jadi tidak ada titik peta untuk data ini.</p></div></div>
<div class="col-lg-4"><div class="card card-eco p-3 h-100"><b>Import dataset (CSV)</b><?php if($adm):?><form method="post" enctype="multipart/form-data" data-load class="mt-2"><input type="hidden" name="t" value="<?=csrf()?>"><input class="form-control form-control-sm mb-2" type="file" name="csv" accept=".csv" required><button class="btn btn-eco btn-sm w-100">Validasi &amp; import</button></form><p class="small text-muted mt-2 mb-0">Kolom: <?=e(implode(', ',$NEED))?>. Seluruh file divalidasi dulu; jika ada baris salah, tidak ada yang disimpan. Import ulang tidak menggandakan data.</p><?php else:?><p class="small text-muted mb-0 mt-2">Import hanya untuk admin.</p><?php endif?></div></div></div>
<form class="row g-2 mb-3"><div class="col-md-3"><input class="form-control" name="q" placeholder="Cari kabupaten/kota" value="<?=e($sq)?>"></div><div class="col-6 col-md-2"><select class="form-select" name="tahun"><option value="">Semua tahun</option><?php foreach($yrs as $y):?><option <?=$ty==$y?'selected':''?>><?=$y?></option><?php endforeach?></select></div><div class="col-6 col-md-2"><select class="form-select" name="periode"><option value="">Semua periode</option><?php foreach($pers as $y):?><option <?=$tp===$y?'selected':''?>><?=e($y)?></option><?php endforeach?></select></div>
<div class="col-md-3"><select class="form-select" name="urut"><?php foreach(['tahun_desc'=>'Tahun terbaru','tahun_asc'=>'Tahun terlama','harian_desc'=>'Harian tertinggi','harian_asc'=>'Harian terendah','tahunan_desc'=>'Tahunan tertinggi','tahunan_asc'=>'Tahunan terendah','nama'=>'Nama wilayah'] as $k=>$l):?><option value="<?=$k?>" <?=$so==$k?'selected':''?>><?=$l?></option><?php endforeach?></select></div><div class="col-md-2 d-flex gap-1"><button class="btn btn-eco flex-fill">Terapkan</button><a class="btn btn-outline-success" title="Ekspor CSV" href="<?=e('?'.http_build_query(array_merge($_GET,['export'=>'csv'])))?>"><i class="bi bi-download"></i></a></div></form>
<div class="card card-eco p-3"><?php if(!$rows):?><p class="text-muted text-center my-4"><?=$all?'Tidak ada data yang cocok dengan filter.':'Belum ada data SIPSN. Import file CSV atau jalankan tools/sipsn.sql di database.'?></p><?php else:?><div class="table-responsive"><table class="table align-middle small"><tr><th>Tahun</th><th>Periode</th><th>Kabupaten/Kota</th><th class="text-end">Timbulan harian</th><th class="text-end">Timbulan tahunan</th><th></th></tr>
<?php foreach($rows as $r):?><tr><td><?=e($r['tahun'])?></td><td><?=e($r['periode'])?></td><td><?=e($r['nama_kabkota'])?></td><td class="text-end"><?=nf($r['jml_timbulan_harian'],2)?></td><td class="text-end"><?=nf($r['jml_timbulan_tahun'],2)?></td><td><a class="btn btn-sm btn-outline-success" href="analisis.php?kab=<?=urlencode($r['nama_kabkota'])?>&amp;tahun=<?=(int)$r['tahun']?>">Detail</a></td></tr><?php endforeach?></table></div>
<div class="d-flex justify-content-between align-items-center flex-wrap gap-2"><small class="text-muted"><?=$tot?> data &middot; halaman <?=$pg?> dari <?=$pages?></small><div class="btn-group btn-group-sm"><a class="btn btn-outline-secondary <?=$pg<=1?'disabled':''?>" href="<?=e($qs($pg-1))?>">&laquo;</a><a class="btn btn-outline-secondary <?=$pg>=$pages?'disabled':''?>" href="<?=e($qs($pg+1))?>">&raquo;</a></div></div><?php endif?></div>
